def fit(f,n,tries=6):
    best=None
    rng=np.random.default_rng(0)
    for k in range(tries):
        x0=rng.normal(0,1,n)
        try:
            s=least_squares(lambda p:np.nan_to_num(f(p)-y,nan=1e3),x0)
